<script setup lang="ts">
import {onMounted,ref} from 'vue';import {libraryApi,type LibraryFile,type LibraryServer} from '@/lib/api';import Table from '@/components/ui/Table.vue';import Badge from '@/components/ui/Badge.vue';import Card from '@/components/ui/Card.vue';const files=ref<LibraryFile[]>([]);const servers=ref<LibraryServer[]>([]);const error=ref('');onMounted(async()=>{try{[files.value,servers.value]=await Promise.all([libraryApi.listFiles(),libraryApi.getServers()])}catch(e){error.value=e instanceof Error?e.message:'加载失败'}});const total=()=>files.value.reduce((n,f)=>n+f.size,0);const countByQuality=()=>files.value.reduce((a,f)=>(a[f.quality_bucket]=(a[f.quality_bucket]??0)+1,a),{} as Record<string,number>)
</script>
<template><div class="space-y-5"><div><h2 class="text-xl font-semibold">媒体资产</h2><p class="text-sm text-muted">库内文件与媒体服务器状态</p></div><div v-if="error" class="text-status-missing">{{error}}</div><div class="grid gap-3 sm:grid-cols-3"><Card class="p-4"><p class="text-sm text-muted">文件数</p><p class="mt-2 text-2xl font-semibold">{{files.length}}</p></Card><Card class="p-4"><p class="text-sm text-muted">样本总大小</p><p class="mt-2 text-2xl font-semibold">{{(total()/1024**3).toFixed(1)}} GB</p></Card><Card class="p-4"><p class="text-sm text-muted">画质分布</p><p class="mt-2 text-sm">{{JSON.stringify(countByQuality())}}</p></Card></div><div class="grid gap-3 sm:grid-cols-2"><Card v-for="server in servers" :key="server.provider" class="flex items-center justify-between p-4"><span>{{server.provider}}</span><Badge :tone="server.valid?'good':'muted'">{{server.configured?'已配置':'未配置'}}</Badge></Card></div><Table><thead class="border-b border-border text-muted"><tr><th class="p-3">媒体 ID</th><th class="p-3">文件路径</th><th class="p-3">画质</th><th class="p-3">大小</th></tr></thead><tbody><tr v-for="file in files" :key="file.id" class="border-b border-border"><td class="p-3">{{file.media_id}}</td><td class="max-w-80 truncate p-3" :title="file.path">{{file.path}}</td><td class="p-3">{{file.quality_bucket}}</td><td class="p-3">{{(file.size/1024**3).toFixed(2)}} GB</td></tr></tbody></Table></div></template>